engine.activityValidate:
function activityValidate(entry) {
  var SCHEMA = window.eli.activity && window.eli.activity.SCHEMA;
  if (!SCHEMA) return null;
  if (!entry || typeof entry !== "object") return "entry must be an object";
  var keys = Object.keys(SCHEMA);
  for (var i = 0; i < keys.length; i++) {
    var key = keys[i];
    var spec = SCHEMA[key];
    var v = entry[key];
    if (spec.required && (v == null || v === "")) {
      return "missing required field: " + key;
    }
    if (v != null && typeof v !== spec.type) {
      return "field '" + key + "' should be " + spec.type + ", got " + typeof v;
    }
  }
  return null;
}

engine.activityAgo:
function activityAgo(ts) {
  if (!ts) return "";
  var sec = Math.floor((Date.now() - ts) / 1000);
  if (sec < 5) return "just now";
  if (sec < 60) return sec + "s";
  if (sec < 3600) return Math.floor(sec / 60) + "m";
  if (sec < 86400) return Math.floor(sec / 3600) + "h";
  return Math.floor(sec / 86400) + "d";
}

view.renderActivity:
function renderActivity(opts) {
  var panel = document.createElement("div");
  panel.className = "feed-container";
  panel.id = "_eli3_activity_panel";
  var head = document.createElement("div");
  head.className = "feed-header";
  head.innerHTML =
    '<div class="feed-header-left">' +
      '<span class="feed-header-icon">⚡</span>' +
      '<span class="feed-header-title">ELI SESSION FEED</span>' +
    '</div>' +
    '<div class="feed-header-count" id="_eli3_activity_count">0</div>';
  panel.appendChild(head);
  var list = document.createElement("div");
  list.className = "feed-list";
  list.id = "_eli3_activity_rail";
  panel.appendChild(list);
  // Populate before mount so getElementById can't race the DOM.
  populateActivityList(list, opts);
  return panel;
}

// refreshActivity(opts) — looks up the existing rail and repaints.
// Called from bus subscribers on activity:added / activity:updated.

view.refreshActivity:
function refreshActivity(opts) {
  var list = document.getElementById("_eli3_activity_rail");
  if (!list) return;
  populateActivityList(list, opts);
}

// populateActivityList(list, opts) — fill the rail from opts.list().

view.populateActivityList:
function populateActivityList(list, opts) {
  list.innerHTML = "";
  var entries = (opts && typeof opts.list === "function") ? opts.list({ limit: 30 }) : [];
  // Walk up from `list` instead of getElementById — _renderActivity calls
  // this BEFORE appending the panel to the DOM, so getElementById was
  // returning null and the count stayed at 0.
  var panel = list.closest(".feed-container") || list.parentNode;
  var countEl = panel ? panel.querySelector(".feed-header-count") : null;
  if (countEl) countEl.textContent = entries.length;
  if (!entries.length) {
    var empty = document.createElement("div");
    empty.className = "_eli3_activity_empty";
    empty.textContent = "No activity yet.";
    list.appendChild(empty);
    return;
  }
  // Chronological order — oldest left, newest right. Gold ➔ arrow between.
  entries.forEach(function (e, idx) {
    if (idx > 0) {
      var arrow = document.createElement("div");
      arrow.className = "feed-arrow";
      arrow.textContent = "➔";
      list.appendChild(arrow);
    }
    appendFeedItem(list, e, opts);
  });
  // Auto-scroll to right edge so newest entry is visible.
  setTimeout(function () { list.scrollLeft = list.scrollWidth; }, 0);
}

// appendFeedItem(list, e, opts) — render one chip + wire restore click.

view.appendFeedItem:
function appendFeedItem(list, e, opts) {
  var ago = (opts && typeof opts.ago === "function") ? opts.ago : function (ts) { return ts ? String(ts) : ""; };
  var dispatch = opts && opts.dispatch;
  var toast = opts && opts.toast;
  var item = document.createElement("div");
  item.className = "feed-item";
  var label = e.label || e.type || "Event";
  var summary = e.summary || "";
  var canRestore = !!(e.payload && e.restoreChannel && e.restoreKey);
  if (canRestore) {
    item.classList.add("restorable");
    item.title = label + (summary ? " — " + summary : "") + " (" + ago(e.timestamp) + ") — click to restore";
    item.style.cursor = "pointer";
    item.onclick = function () {
      try {
        var handler = (typeof dispatch === "function") ? dispatch(e.restoreChannel, e.restoreKey) : null;
        if (typeof handler === "function") {
          handler(e.payload);
          return;
        }
        if (typeof toast === "function") toast("This activity can't be restored (handler missing).", "warn");
      } catch (err) {
        if (typeof toast === "function") toast("Restore failed: " + (err && err.message || "unknown"), "err");
      }
    };
  } else {
    item.title = label + (summary ? " — " + summary : "") + " (" + ago(e.timestamp) + ")";
  }
  var icon = document.createElement("div");
  icon.className = "feed-icon";
  icon.textContent = e.icon || "•";
  item.appendChild(icon);
  var body = document.createElement("div");
  body.className = "feed-body";
  var lbl = document.createElement("div");
  lbl.className = "feed-label";
  lbl.textContent = label;
  body.appendChild(lbl);
  if (summary) {
    var sm = document.createElement("div");
    sm.className = "feed-summary";
    sm.textContent = summary;
    body.appendChild(sm);
  }
  item.appendChild(body);
  var meta = document.createElement("div");
  meta.className = "feed-meta";
  var time = document.createElement("div");
  time.className = "feed-time";
  time.textContent = ago(e.timestamp);
  meta.appendChild(time);
  if (canRestore) {
    var restore = document.createElement("div");
    restore.className = "feed-restore";
    restore.textContent = "↺ RESTORE";
    meta.appendChild(restore);
  }
  item.appendChild(meta);
  list.appendChild(item);
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["eli-activity"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var validate = efns.activityValidate;
  var ago = efns.activityAgo;
  var renderActivity = vfns.renderActivity;
  var refreshActivity = vfns.refreshActivity;
  if (!validate || !ago || !renderActivity || !refreshActivity) {
    eli.log.event("tool", "eli_activity_load_failed", {
      hasValidate: !!validate, hasAgo: !!ago,
      hasRenderActivity: !!renderActivity, hasRefreshActivity: !!refreshActivity,
    });
    return;
  }

  // ─── Storage-backed ring (replaces kernel §13 IIFE) ──────────────
  var STORE_CONFIG = "config";
  var ACTIVITY_KEY = "activity_feed";
  var MAX_ENTRIES = 200;
  var PERSIST_DEBOUNCE_MS = 1000;

  // Migrate whatever the kernel stub buffered before we evaluated.
  // The stub stores its in-memory ring on window.eli.activity._stubRing.
  var _ring = (window.eli.activity && Array.isArray(window.eli.activity._stubRing))
    ? window.eli.activity._stubRing.slice()
    : [];
  var _persistTimer = null;
  var _hydrated = false;

  function _schedulePersist() {
    if (_persistTimer) return;
    _persistTimer = setTimeout(function () {
      _persistTimer = null;
      _persist();
    }, PERSIST_DEBOUNCE_MS);
  }
  function _persist() {
    return eli.storage.put(STORE_CONFIG, {
      key: ACTIVITY_KEY,
      entries: _ring.slice(),
      updatedAt: Date.now(),
    }).catch(function () { /* tolerate */ });
  }

  function add(entry) {
    if (entry && typeof entry === "object") {
      if (!entry.timestamp) entry.timestamp = Date.now();
      if (!entry.id) entry.id = "act_" + entry.timestamp + "_" + Math.random().toString(36).slice(2, 8);
    }
    var err = validate(entry);
    if (err) {
      throw new eli.errors.ValidationError("activity.add: " + err, { meta: { entry: entry } });
    }
    _ring.push(entry);
    while (_ring.length > MAX_ENTRIES) _ring.shift();
    _schedulePersist();
    try { eli.bus.emit("activity:added", entry); } catch (e) { /* noop */ }
    return entry;
  }

  var _RESERVED_UPDATE_KEYS = { id: true, timestamp: true };
  function update(id, patch) {
    if (!id || !patch || typeof patch !== "object") return null;
    for (var i = _ring.length - 1; i >= 0; i--) {
      var e = _ring[i];
      if (e && e.id === id) {
        Object.keys(patch).forEach(function (k) {
          if (_RESERVED_UPDATE_KEYS[k]) return;
          e[k] = patch[k];
        });
        e.updatedAt = Date.now();
        var err = validate(e);
        if (err) {
          throw new eli.errors.ValidationError(
            "activity.update: patch produced invalid entry: " + err,
            { meta: { id: id, patch: patch } }
          );
        }
        _schedulePersist();
        try { eli.bus.emit("activity:updated", e); } catch (busErr) { /* noop */ }
        return e;
      }
    }
    return null;
  }

  function list(opts) {
    opts = opts || {};
    var src = opts.includeInternal
      ? _ring
      : _ring.filter(function (e) {
          return !(e && typeof e.type === "string" && e.type.charAt(0) === "_");
        });
    var limit = opts.limit ? Math.min(opts.limit, src.length) : src.length;
    return src.slice(-limit);
  }

  function clear() {
    _ring = [];
    if (_persistTimer) { clearTimeout(_persistTimer); _persistTimer = null; }
    return eli.storage.delete(STORE_CONFIG, ACTIVITY_KEY).catch(function () { /* tolerate */ });
  }

  function hydrate() {
    return eli.storage.get(STORE_CONFIG, ACTIVITY_KEY).then(function (row) {
      if (row && Array.isArray(row.entries)) {
        // Merge: persisted ring + any in-memory entries from the stub.
        // Dedup by id; the stub-buffered entries always win (most recent).
        var bySeenId = {};
        _ring.forEach(function (e) { if (e && e.id) bySeenId[e.id] = true; });
        var merged = row.entries.filter(function (e) { return !(e && e.id && bySeenId[e.id]); });
        _ring = merged.concat(_ring).slice(-MAX_ENTRIES);
      }
      _hydrated = true;
      return _ring.length;
    }).catch(function () { _hydrated = true; return 0; });
  }

  // Overwrite the kernel stub with the real implementation. SCHEMA stays
  // kernel-side (eli.activity.SCHEMA) — only behavior moves.
  eli.activity.add = add;
  eli.activity.update = update;
  eli.activity.list = list;
  eli.activity.clear = clear;
  eli.activity.hydrate = hydrate;
  eli.activity.isHydrated = function () { return _hydrated; };
  eli.activity.MAX_ENTRIES = MAX_ENTRIES;
  // Cleanup the stub's buffer reference — we've drained it into _ring.
  try { delete eli.activity._stubRing; } catch (e) {}

  // ─── Renderer slot + bus wiring ──────────────────────────────────
  function _renderOpts() {
    return {
      list: list,
      ago: ago,
      dispatch: function (channel, key) { return eli.get && eli.get(channel, key); },
      toast: function (msg, kind) { if (typeof showToast === "function") showToast(msg, kind); },
    };
  }

  if (eli.dashboard && typeof eli.dashboard.registerHomeSlot === "function") {
    eli.dashboard.registerHomeSlot("activity_feed", function (opts) {
      // Kernel slot infra hands us a mount; we paint our panel into it.
      // `position: "below"` puts the slot in the after-tiles host
      // (_eli3_below_slots), preserving the prior visual position the
      // kernel-rendered feed had. Pre-Batch-7 kernels without the
      // position option fall back to "above" — visible position drift
      // for users on old kernels but no breakage.
      var mount = opts && opts.mount;
      if (!mount) return;
      mount.innerHTML = "";
      mount.appendChild(renderActivity(_renderOpts()));
    }, { order: 50, position: "below" });
  }

  // Refresh on add / update — the bus emit comes from add/update above
  // (and from any other code path that emits these events).
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("activity:added", function () { refreshActivity(_renderOpts()); });
    eli.bus.on("activity:updated", function () { refreshActivity(_renderOpts()); });
  }

  // Hydrate from IDB on first load. After hydrate completes, force a
  // refresh so the slot picks up the persisted entries.
  hydrate().then(function () {
    refreshActivity(_renderOpts());
  });

  eli.log.event("tool", "eli_activity_initialized", { ringSize: _ring.length });
}

jsonTools.css:
/* tools/eli-activity/style.css
 * Activity feed (session feed) styles. Moved from taskpane_v3.css 1165-1351
 * in Batch 7 (2026-05-11). Includes the dark-mode default + the
 * light-mode (.beta-ui-active.light-mode) overrides + the empty-state
 * label. CSS variables (--bg-feed, --color-gold, --space-*, --font-*)
 * are kernel-defined in :root so this bundle inherits them.
 */

/* ─── §8  Activity feed (session feed)
 *   What: `.feed-container`, `.feed-header`, `.feed-list`, `.feed-item`,
 *         `.feed-arrow`, `.feed-icon`, `.feed-body`, `.feed-restore`.
 *   Who emits: kernel's _renderActivity.
 *   Modifier: `.feed-item.restorable` → click-to-restore.
 */
/* Feed container — no padding-bottom inside (dark bg ends right at the
 * chip rail). All breathing room sits OUTSIDE the container as
 * margin-bottom — 12px transparent gap before the footer. */
.feed-container {
  flex: 0 0 auto;
  margin-top: auto;
  background: var(--bg-feed);
  border-top: 1px solid var(--border-subtle);
  padding-bottom: 0;
  margin-bottom: var(--space-3);    /* 12px gap before footer */
}
.feed-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px var(--space-3);
  background: var(--bg-feed-row-grad);
  border-bottom: 1px solid var(--border-subtle);
}
.feed-header-left { display: flex; align-items: center; gap: 6px; }
.feed-header-icon { font-size: 12px; filter: drop-shadow(0 0 var(--space-1) rgba(201, 162, 39, 0.5)); }
.feed-header-title {
  font: var(--weight-bold) var(--font-xs)/1.3 var(--font-family);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-gold);
}
/* Count pill — gold square with dark text. v2-exact. */
.feed-header-count {
  font: var(--weight-extrabold) var(--font-xs)/1.2 var(--font-family);
  color: #0d1b2a;
  background: var(--color-gold-warm);
  padding: 1px 7px;
  min-width: 16px;
  text-align: center;
}

.feed-list,
._eli3_activity_rail {
  display: flex;
  flex-direction: row;
  gap: 6px;
  padding: var(--space-1) 6px;   /* 4px 6px — v2-exact */
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
}
.feed-list::-webkit-scrollbar,
._eli3_activity_rail::-webkit-scrollbar { height: 6px; }
.feed-list::-webkit-scrollbar-thumb,
._eli3_activity_rail::-webkit-scrollbar-thumb { background: rgba(201, 162, 39, 0.3); }
.feed-arrow {
  align-self: center;
  color: var(--color-gold);
  font-weight: var(--weight-extrabold);
  flex-shrink: 0;
  font-size: 12px;
}
/* Chip — symmetric padding top/bottom. `position: relative` so the
 * restore overlay (.feed-restore) anchors to this box. */
.feed-item {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: var(--space-1) var(--space-2);
  border: 1px solid var(--border-subtle);
  background: var(--bg-overlay-soft);
  width: 96px;
  flex-shrink: 0;
  text-align: center;
  transition: background 0.15s, border-color 0.15s;
  overflow: hidden;
}
.feed-item:hover {
  background: var(--bg-overlay-soft-h);
  border-color: var(--border-subtle-h);
}
.feed-item.restorable { cursor: pointer; }
.feed-item.restorable:hover {
  border-color: rgba(201, 162, 39, 0.7);
  box-shadow: 0 2px 6px rgba(201, 162, 39, 0.15);
}
.feed-icon { font-size: 18px; }
.feed-body {
  display: flex;
  flex-direction: column;
  gap: 1px;
  width: 100%;
}
.feed-label {
  font: var(--weight-bold) var(--font-xs)/1.2 var(--font-family);
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: var(--color-gold);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.feed-summary {
  font: var(--weight-semibold) var(--font-xs)/1.2 var(--font-family);
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  max-height: 22px;
}
.feed-meta { width: 100%; }
.feed-time {
  font: var(--weight-semibold) 8px/1 var(--font-family);
  color: var(--text-status-footer);
  text-align: center;
}
/* Restore label — full-chip overlay on hover. Gold background, dark
 * text. Hidden completely (display:none) when not hovered so it doesn't
 * reserve layout space inside the chip. */
.feed-restore {
  display: none;
  position: absolute;
  inset: 0;
  background: var(--color-gold-warm);
  color: #0d1b2a;
  font: var(--weight-extrabold) 10px/1 var(--font-family);
  letter-spacing: 0.8px;
  text-transform: uppercase;
  text-align: center;
  align-items: center;
  justify-content: center;
  z-index: 5;
}
.feed-item.restorable:hover .feed-restore { display: flex; }

._eli3_activity_empty {
  padding: 6px 10px;
  color: var(--text-status-footer);
  font-style: italic;
  font-size: var(--font-sm);
}

/* Feed light-mode overrides (v2-parity) */
body.light-mode.beta-ui-active .feed-container {
  background: linear-gradient(180deg, #ffffff 0%, #f6f8fb 100%) !important;
  border: 1px solid #c2cdd9 !important;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06), 0 1px 3px rgba(0, 0, 0, 0.04) !important;
}
body.light-mode.beta-ui-active .feed-header {
  background: linear-gradient(180deg, #edf1f7 0%, #e4eaf2 100%) !important;
  border-bottom: 1px solid #cdd6e1 !important;
}
body.light-mode.beta-ui-active .feed-header-title,
body.light-mode.beta-ui-active .feed-header-left {
  color: #334155 !important;
  text-shadow: none !important;
}
body.light-mode.beta-ui-active .feed-header-count {
  color: #334155 !important;
  background: #e2e8f0 !important;
}
body.light-mode.beta-ui-active .feed-list { background: transparent !important; }
body.light-mode.beta-ui-active .feed-item {
  background: linear-gradient(180deg, #ffffff 0%, #f6f8fb 100%) !important;
  border: 1px solid #c2cdd9 !important;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04) !important;
}
body.light-mode.beta-ui-active .feed-item:hover {
  background: linear-gradient(180deg, #ffffff 0%, #edf1f7 100%) !important;
  border-color: #8896a7 !important;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.07) !important;
}
body.light-mode.beta-ui-active .feed-label { color: #1e293b !important; }
body.light-mode.beta-ui-active .feed-summary { color: #475569 !important; font-weight: 600 !important; }
body.light-mode.beta-ui-active .feed-time { color: #64748b !important; }
body.light-mode.beta-ui-active .feed-restore {
  background: #ffffff !important;
  color: #2563eb !important;
}
